package example;

import org.eclipse.core.resources.ResourcesPlugin;
import org.eclipse.core.runtime.Preferences;
import org.eclipse.core.runtime.Preferences.IPropertyChangeListener;

public class MyClass implements IPropertyChangeListener {
    private Preferences preferences = ResourcesPlugin.getPlugin().getPluginPreferences();

    public MyClass() {
        // Original deprecated API usage
        this.preferences.addPropertyChangeListener(this);
    }

    @Override
    public void propertyChange(Preferences.PropertyChangeEvent event) {
        System.out.println("Property changed: " + event.getProperty() + " -> " + event.getNewValue());
    }

    public void anotherMethod() {
        // Other method calls on 'preferences' should not be affected by this rule
        preferences.setValue("test", true);
    }
}

afterExample:
package example;

import org.eclipse.core.resources.ResourcesPlugin;
import org.eclipse.core.runtime.Preferences;
import org.eclipse.core.runtime.Preferences.IPropertyChangeListener;
import org.eclipse.core.runtime.preferences.InstanceScope;
import org.eclipse.core.runtime.preferences.IEclipsePreferences; // Although IPropertyChangeListener is replaced by IEclipsePreferences.IPreferenceChangeListener in the commit, this specific rule only targets the method call, so the interface remains unchanged in this rule's output example.

public class MyClass implements IPropertyChangeListener {
    private Preferences preferences = ResourcesPlugin.getPlugin().getPluginPreferences();

    public MyClass() {
        // Replaced with new Equinox Preferences API
        InstanceScope.INSTANCE.getNode(ResourcesPlugin.PI_RESOURCES).addPreferenceChangeListener(this);
    }

    @Override
    public void propertyChange(Preferences.PropertyChangeEvent event) {
        System.out.println("Property changed: " + event.getProperty() + " -> " + event.getNewValue());
    }

    public void anotherMethod() {
        preferences.setValue("test", true);
    }
}

