package example;

import java.beans.PropertyChangeListener;
import java.beans.PropertyChangeSupport;
import java.beans.PropertyChangeEvent;

public class OtherClass {
    private PropertyChangeSupport support = new PropertyChangeSupport(this);

    public OtherClass(PropertyChangeListener listener) {
        // This call should NOT match, as 'support' is of type PropertyChangeSupport, not Preferences
        support.addPropertyChangeListener(listener);
    }

    public void firePropertyChange() {
        support.firePropertyChange(new PropertyChangeEvent(this, "someProperty", "oldValue", "newValue"));
    }
}
